<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Session\Domain\SessionInfo;
use Civi\Lughauth\Features\OAuth\Session\Domain\TemporalAuthCode;
use Civi\Lughauth\Features\OAuth\Session\Domain\Exception\SignatureVerificationException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;

final class SessionDomainUnitTest extends TestCase
{
    public function test_session_info_stores_properties(): void
    {
        $si = new SessionInfo(
            csid: 'csid-1',
            withMfa: true,
            issuer: 'https://iss',
            userId: 'user-x',
            clientId: 'client-y',
        );

        $this->assertSame('csid-1', $si->csid);
        $this->assertTrue($si->withMfa);
        $this->assertSame('https://iss', $si->issuer);
        $this->assertSame('user-x', $si->userId);
        $this->assertSame('client-y', $si->clientId);
    }

    public function test_temporal_auth_code_stores_properties(): void
    {
        $result = new AuthenticationResult(valid: true, id: 'u1');
        $client = new ClientData('c', ['code'], true);
        $request = new AuthenticationRequest($client, 'openid', 'https://cb');

        $code = new TemporalAuthCode(
            data: $result,
            client: $client,
            nonce: 'nonce-xyz',
            request: $request,
            codeChallenge: 'challenge-abc',
            codeChallengeMethod: 'S256',
        );

        $this->assertSame($result, $code->data);
        $this->assertSame($client, $code->client);
        $this->assertSame('nonce-xyz', $code->nonce);
        $this->assertSame($request, $code->request);
        $this->assertSame('challenge-abc', $code->codeChallenge);
        $this->assertSame('S256', $code->codeChallengeMethod);
    }

    public function test_temporal_auth_code_optional_fields_null_by_default(): void
    {
        $result = new AuthenticationResult(valid: true);
        $client = new ClientData('c', [], false);
        $request = new AuthenticationRequest($client, '', '');

        $code = new TemporalAuthCode($result, $client, '', $request);

        $this->assertNull($code->codeChallenge);
        $this->assertNull($code->codeChallengeMethod);
    }

    public function test_signature_verification_exception_is_runtime_exception(): void
    {
        $ex = new SignatureVerificationException('bad sig');
        $this->assertInstanceOf(\RuntimeException::class, $ex);
        $this->assertSame('bad sig', $ex->getMessage());
    }
}
